   101	// searchVerifySubject is what the derivation knows about the edit it has to verify.
   102	type searchVerifySubject struct {
   103		// sourcePath is the file the top hit is in: the file the patch lands in.
   104		sourcePath string
   105		// testPath and testName come from the covering test, and are empty when the payload found none.
   106		testPath string
   107		testName string
   108		// testEvidence names where testPath came from, so the derivation the block reports is the truth
   109		// rather than a label: the payload's covering test, or a conventional mirror file that exists.
   110		testEvidence string
   111	}
   112	
   113	// buildSearchVerifyCommand derives the command, or returns nil.
   114	func buildSearchVerifyCommand(
   115		results []SearchResult,
   116		evidence searchVerifyEvidence,
   117	) *SearchVerifyCommand {
   118		subject, ok := searchVerifySubjectFor(results)
   119		if !ok {
   120			return nil
   121		}
   122		if subject.testPath == "" {
   123			// The payload found no covering test, but the repository's own layout often names one anyway.
   124			// A conventional mirror path that EXISTS is repository evidence in exactly the same sense a
   125			// build manifest is — the file is either there or it is not, nothing is inferred.
   126			if mirror := searchVerifyMirrorTest(subject.sourcePath, &evidence); mirror != "" {
   127				subject.testPath = mirror
   128				subject.testEvidence = "mirror test file"
   129			}
   130		}
   131		command := deriveSearchVerifyCommand(subject, &evidence)
   132		if command == nil {
   133			// No narrow command could be derived — most often because the payload found no covering test
   134			// (a `test_<name>` minitest file the mirror lookup cannot name, a suite with no per-file
   135			// selector). Rather than emit nothing — which, paired with the stop-early doctrine, is what
   136			// lets an agent skip verification and ship a confident-but-wrong patch — fall back to the
   137			// repository's own WHOLE-SUITE invocation. These are canonical commands (`go test ./...`,
   138			// `bundle exec rake test`) that are guaranteed to RUN, so the "silence over a wrong command"
   139			// rule still holds: the failure mode it guards against (an error about the invocation, not
   140			// the code) cannot happen here. The command is slower and unfiltered, so it is labeled as the
   141			// whole suite; a slow-but-real verification beats a whole failed task.
   142			command = deriveSearchVerifySuiteCommand(subject, &evidence)
   143		}
   144		if command == nil {
   145			return nil
   146		}
   147		if searchVerifyCommandCost(command) > searchVerifyCommandMaxBytes {
   148			return nil
   149		}
   150		return command
   151	}
