   153	// searchVerifySubjectFor reads the subject out of the payload: the top candidate fix site, and
   154	// the narrowest test the payload can point at.
   155	//
   156	// A ranked hit that is ITSELF a test file counts twice over, and both readings matter:
   157	//
   158	//   - It is not the fix site. VERIFY answers "how do I exercise the file I am changing", so a
   159	//     test at rank 1 must not become sourcePath — the manifest search would then run from the
   160	//     test tree and the mirror lookup would look for the test's own test.
   161	//   - It IS a test path, and a better one than a guess. The covering-test BLOCK deliberately
   162	//     declines to print a test the ranking already shows (searchCoveringTestAlreadySurfaced),
   163	//     so a payload whose ranking promoted the test has no covering-test section at all. Reading
   164	//     testPath only out of that section made VERIFY degrade to the module root in exactly the
   165	//     case where the payload knew the test file best — it was printing it at rank 1.
   166	//
   167	// The covering-test section still wins when both exist: it carries the test NAME, which narrows
   168	// the command from a file to a single case.
   169	func searchVerifySubjectFor(results []SearchResult) (searchVerifySubject, bool) {
   170		subject := searchVerifySubject{}
   171		rankedTestPath, rankedTestName := "", ""
   172		for _, result := range results {
   173			switch result.Section {
   174			case searchSectionPrimary:
   175				if result.FilePath == "" || NonProgramTextPath(result.FilePath) {
   176					continue
   177				}
   178				if searchTestArtifactPath(searchLowerPath(result.FilePath)) {
   179					if rankedTestPath == "" {
   180						rankedTestPath = filePathToSlash(result.FilePath)
   181						rankedTestName = searchVerifyTestName(result)
   182					}
   183					continue
   184				}
   185				if subject.sourcePath == "" {
   186					subject.sourcePath = filePathToSlash(result.FilePath)
   187				}
   188			case searchSectionCoveringTest:
   189				if subject.testPath == "" && result.FilePath != "" {
   190					subject.testPath = filePathToSlash(result.FilePath)
   191					subject.testName = searchVerifyTestName(result)
   192					subject.testEvidence = "covering test"
   193				}
   194			}
   195		}
   196		if subject.testPath == "" && rankedTestPath != "" {
   197			subject.testPath = rankedTestPath
   198			subject.testName = rankedTestName
   199			subject.testEvidence = "ranked test"
   200		}
   201		// A payload whose every program-text hit is a test still has a subject: the test is the thing
   202		// to run, and it is also the path the manifest search has to start from.
   203		if subject.sourcePath == "" {
   204			subject.sourcePath = rankedTestPath
   205		}
   206		return subject, subject.sourcePath != ""
   207	}
