   209	// searchVerifyTestName is the covering test's own function name, unqualified: it is what every test
   210	// runner's filter takes. A qualified name is deliberately reduced — `Class.method` is not a filter
   211	// in most runners, and half a filter is worse than none.
   212	func searchVerifyTestName(result SearchResult) string {
   213		name := result.SymbolName
   214		if name == "" && result.QualifiedName != "" {
   215			parts := strings.Split(result.QualifiedName, ".")
   216			name = parts[len(parts)-1]
   217		}
   218		if strings.ContainsAny(name, " ()<>{}'\"`$&|;") {
   219			return ""
   220		}
   220		}
   221		return name
   222	}
