   224	// searchVerifyTestAffixes are the ways a test file is named after the file it tests, and
   225	// searchVerifyTestDirs the directory swaps that put it in a parallel tree. The two are combined, so
   226	// `src/Foo.php` -> `tests/FooTest.php` and `hooks/src/index.js` -> `hooks/test/index.test.js` are the
   227	// same rule rather than two.
   228	var (
   229		searchVerifyTestAffixes = []string{"_test", ".test", "Test", "_spec", ".spec", "Spec", "-test"}
   230		searchVerifyTestDirs    = [][2]string{
   231			{"src/main/java/", "src/test/java/"},
   232			{"src/main/kotlin/", "src/test/kotlin/"},
   233			{"src/main/", "src/test/"},
   234			{"src/", "tests/"},
   235			{"src/", "test/"},
   236			{"src/", "spec/"},
   237			{"lib/", "test/"},
   238			{"lib/", "spec/"},
   239		}
