   242	// searchVerifyMirrorTest probes the conventional test-file names for a source file and returns the
   243	// first one that EXISTS, or "".
   244	//
   245	// It is bounded: a handful of names beside the file, the same names inside a `__tests__`/`test`
   246	// subdirectory, and the same names in a parallel test tree. Every probe is a read that either finds a
   247	// file or does not, so the result is a fact about the repository and never a guess.
   248	func searchVerifyMirrorTest(sourcePath string, evidence *searchVerifyEvidence) string {
   249		dir := path.Dir(sourcePath)
   250		if dir == "." || dir == "/" {
   251			dir = ""
   252		}
   253		base := path.Base(sourcePath)
   254		stem := searchVerifyStem(base)
   255		extension := strings.TrimPrefix(strings.TrimPrefix(base, stem), ".")
   256		if stem == "" || extension == "" {
   257			return ""
   258		}
   259		for _, affix := range searchVerifyTestAffixes {
   260			candidates := []string{
   261				searchVerifyJoin(dir, stem+affix+"."+extension),
   262				searchVerifyJoin(searchVerifyJoin(dir, "__tests__"), stem+affix+"."+extension),
   263				searchVerifyJoin(searchVerifyJoin(dir, "__tests__"), stem+"."+extension),
   264				searchVerifyJoin(searchVerifyJoin(dir, "test"), stem+affix+"."+extension),
   265				searchVerifyJoin(searchVerifyJoin(dir, "tests"), stem+affix+"."+extension),
   266			}
   267			for _, swap := range searchVerifyTestDirs {
   268				if !strings.HasPrefix(sourcePath, swap[0]) && !strings.Contains(sourcePath, "/"+swap[0]) {
   269					continue
   270				}
   271				mirrored := strings.Replace(sourcePath, swap[0], swap[1], 1)
   272				mirrorDir := path.Dir(mirrored)
   273				if mirrorDir == "." || mirrorDir == "/" {
   274					mirrorDir = ""
   275				}
   276				candidates = append(candidates,
   277					searchVerifyJoin(mirrorDir, stem+affix+"."+extension),
   278					searchVerifyJoin(mirrorDir, stem+"."+extension),
   279				)
   280			}
   281			for _, candidate := range candidates {
   282				if candidate == sourcePath {
   283					continue
   284				}
   285				if evidence.exists(candidate) {
   286					return candidate
   287				}
   288			}
   289		}
   290		return ""
   291	}
