   293	// deriveSearchVerifyCommand walks from the subject's own directory towards the repository root and
   294	// stops at the FIRST manifest that licenses a narrow command.
   295	//
   296	// A manifest that exists but licenses nothing does not stop the walk: a `Cargo.toml` that is only a
   297	// workspace stanza, or a monorepo leaf `package.json` with no test runner in it, is evidence about
   298	// the tree, not about how to run a test, so the walk continues outward to the manifest that is.
   299	func deriveSearchVerifyCommand(subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
   300		dir := path.Dir(subject.sourcePath)
   301		if dir == "." || dir == "/" {
   302			dir = ""
   303		}
   304		for depth := 0; depth <= searchVerifyMaxDepth; depth++ {
   305			for _, derive := range searchVerifyDerivations {
   306				if command := derive(dir, subject, evidence); command != nil {
   307					return command
   308				}
   309			}
   310			if dir == "" {
   311				break
   312			}
   313			parent := path.Dir(dir)
   314			if parent == "." || parent == "/" || parent == dir {
   315				dir = ""
   316				continue
   317			}
   318			dir = parent
   319		}
   320		return nil
   321	}
