   563	// deriveSearchVerifyCargo derives a Cargo command. The package name comes from the manifest's own
   564	// `[package] name`, and the test selector from where the covering test lives: a test under `src/` is
   565	// a unit test in the lib target, a test under `tests/` is its own integration target named after
   566	// the file.
   567	func deriveSearchVerifyCargo(dir string, subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
   568		manifest := searchVerifyJoin(dir, "Cargo.toml")
   569		content, ok := evidence.file(manifest)
   570		if !ok {
   571			return nil
   572		}
   573		name, found := searchVerifyTomlPackageName(content)
   574		if !found {
   575			return nil
   576		}
   577		// `-p` only selects from a workspace. When the crate is not part of one, the command has to run
   578		// in the crate itself.
   579		root, rootFound := evidence.file("Cargo.toml")
   580		workspace := rootFound && strings.Contains(root, "[workspace]")
   581		selector := ""
   582		if workspace {
   583			selector = " -p " + name
   584		}
   585		target, filter, targets := "", "", "package "+name
   586		if relative, inside := searchVerifyRelative(dir, subject.testPath); inside && subject.testPath != "" {
   587			switch {
   588			case strings.HasPrefix(relative, "tests/"):
   589				target = " --test " + searchVerifyStem(relative)
   590			case strings.HasPrefix(relative, "src/"):
   591				target = " --lib"
   592			}
   593			if target != "" {
   594				targets = subject.testPath
   595				if subject.testName != "" {
   596					filter = " " + subject.testName
   597				}
   598			}
   599		}
   600		command := "cargo test" + selector + target + filter
   601		if !workspace {
   602			command = searchVerifyRunIn(dir, "cargo test"+target+filter)
   603		}
   604		derived := "Cargo.toml [package] name"
   605		if workspace {
   606			derived = "root Cargo.toml [workspace] + " + manifest + " package name"
   607		}
   608		if target != "" {
   609			derived += " + " + subject.testEvidence + " path"
   610		}
   611		return &SearchVerifyCommand{Command: command, Targets: targets, DerivedFrom: derived}
   612	}
