   614	// searchVerifyTomlPackageName reads `name` out of a Cargo manifest's `[package]` table. It is a
   615	// line scanner rather than a TOML parser because it needs exactly one key from one table, and a
   616	// dependency on a parser to read one line is a worse trade than a scanner that gives up.
   617	func searchVerifyTomlPackageName(content string) (string, bool) {
   618		inPackage := false
   619		for _, line := range strings.Split(content, "\n") {
   620			trimmed := strings.TrimSpace(line)
   621			if strings.HasPrefix(trimmed, "[") {
   622				inPackage = trimmed == "[package]"
   623				continue
   624			}
   625			if !inPackage || !strings.HasPrefix(trimmed, "name") {
   626				continue
   627			}
   628			_, value, found := strings.Cut(trimmed, "=")
   629			if !found {
   630				continue
   631			}
   632			name := strings.Trim(strings.TrimSpace(value), "\"'")
   633			// `name = { workspace = true }` inherits the name from the workspace, so this manifest does
   634			// not state it and cannot be used as a selector.
   635			if name == "" || strings.ContainsAny(name, "{} \t") {
   636				return "", false
   637			}
   638			return name, true
   639		}
   640		return "", false
   641	}
