   643	// deriveSearchVerifyGo derives a `go test` command for the package the edit lands in, filtered to
   644	// the covering test when there is one. The `-run` pattern is anchored: an unanchored name also runs
   645	// every test whose name contains it.
   646	func deriveSearchVerifyGo(dir string, subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
   647		manifest := searchVerifyJoin(dir, "go.mod")
