568	// deriveSearchVerifyNode derives a JS/TS command from the nearest package.json that actually names
569	// a test runner. A monorepo leaf package with no runner in it is skipped, which is what sends the
570	// walk out to the workspace root where the runner is configured.
571	func deriveSearchVerifyNode(dir string, subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
572		manifest := searchVerifyJoin(dir, "package.json")
573		content, ok := evidence.file(manifest)
574		if !ok {
575			return nil
576		}
577		var parsed struct {
578			Scripts         map[string]string `json:"scripts"`
579			DevDependencies map[string]string `json:"devDependencies"`
580			Dependencies    map[string]string `json:"dependencies"`
581		}
582		if err := json.Unmarshal([]byte(content), &parsed); err != nil {
583			return nil
584		}
585		runner, evidenceKind := "", ""
586		for _, candidate := range searchVerifyNodeRunners {
587			if strings.Contains(parsed.Scripts["test"], candidate.name) {
588				runner, evidenceKind = candidate.command, "scripts.test"
589				break
590			}
591			if _, declared := parsed.DevDependencies[candidate.name]; declared {
592				runner, evidenceKind = candidate.command, "devDependencies"
593				break
594			}
595			if _, declared := parsed.Dependencies[candidate.name]; declared {
596				runner, evidenceKind = candidate.command, "dependencies"
597				break
598			}
599		}
600		if runner == "" || subject.testPath == "" {
601			return nil
602		}
603		relative, inside := searchVerifyRelative(dir, subject.testPath)
604		if !inside {
605			return nil
606		}
607		return &SearchVerifyCommand{
608			Command:     searchVerifyRunIn(dir, runner+" "+relative),
609			Targets:     subject.testPath,
610			DerivedFrom: manifest + " " + evidenceKind + " + " + subject.testEvidence + " path",
611		}
612	}
