680	// deriveSearchVerifyRuby derives an RSpec or a single-file Minitest command. Which one is decided by
681	// where the covering test lives, because that is what the repository itself decided.
682	func deriveSearchVerifyRuby(dir string, subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
683		hasGemfile := evidence.exists(searchVerifyJoin(dir, "Gemfile"))
684		hasRakefile := evidence.exists(searchVerifyJoin(dir, "Rakefile"))
685		if !hasGemfile && !hasRakefile {
686			return nil
687		}
688		if subject.testPath == "" {
689			return nil
690		}
691		relative, inside := searchVerifyRelative(dir, subject.testPath)
692		if !inside {
693			return nil
694		}
695		manifest := searchVerifyJoin(dir, "Rakefile")
696		if !hasRakefile {
697			manifest = searchVerifyJoin(dir, "Gemfile")
698		}
699		switch {
700		case strings.HasPrefix(relative, "spec/") && evidence.exists(searchVerifyJoin(dir, ".rspec")):
701			return &SearchVerifyCommand{
702				Command:     searchVerifyRunIn(dir, "bundle exec rspec "+relative),
703				Targets:     subject.testPath,
704				DerivedFrom: searchVerifyJoin(dir, ".rspec") + " + " + subject.testEvidence + " path",
705			}
706		case strings.HasPrefix(relative, "test/"):
707			return &SearchVerifyCommand{
708				Command:     searchVerifyRunIn(dir, "bundle exec ruby -Itest "+relative),
709				Targets:     subject.testPath,
710				DerivedFrom: manifest + " + " + subject.testEvidence + " path under test/",
711			}
712		}
713		return nil
714	}
